package com.example.studentactivity; import android.os.Bundle; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity; public class SecondaryActivity extends AppCompatActivity { @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_secondary);String name=getIntent().getStringExtra("name"),phone=getIntent().getStringExtra("phone"),dept=getIntent().getStringExtra("department"),gender=getIntent().getStringExtra("gender"),courses=getIntent().getStringExtra("courses");((TextView)findViewById(R.id.tvName)).setText("Name : "+name);((TextView)findViewById(R.id.tvPhone)).setText("Phone : "+phone);((TextView)findViewById(R.id.tvDepartment)).setText("Department : "+dept);((TextView)findViewById(R.id.tvGender)).setText("Gender : "+gender);((TextView)findViewById(R.id.tvCourses)).setText("Preferred Courses : "+courses);}}
